public class InnerTableIcebergMetadataFactory(Action<Humidifier.S3Tables.TableTypes.IcebergMetadata> factoryAction = null) : SubResourceFactory<Humidifier.S3Tables.TableTypes.IcebergMetadata>
{

    internal InnerTableIcebergSchemaFactory IcebergSchemaFactory { get; set; }

    internal InnerTableIcebergSortOrderFactory IcebergSortOrderFactory { get; set; }

    internal InnerTableIcebergSchemaV2Factory IcebergSchemaV2Factory { get; set; }

    internal InnerTableIcebergPartitionSpecFactory IcebergPartitionSpecFactory { get; set; }

    protected override Humidifier.S3Tables.TableTypes.IcebergMetadata Create()
    {
        var icebergMetadataResult = CreateIcebergMetadata();
        factoryAction?.Invoke(icebergMetadataResult);

        return icebergMetadataResult;
    }

    private Humidifier.S3Tables.TableTypes.IcebergMetadata CreateIcebergMetadata()
    {
        var icebergMetadataResult = new Humidifier.S3Tables.TableTypes.IcebergMetadata();

        return icebergMetadataResult;
    }
    public override void CreateChildren(Humidifier.S3Tables.TableTypes.IcebergMetadata result)
    {
        base.CreateChildren(result);

        result.IcebergSchema ??= IcebergSchemaFactory?.Build();
        result.IcebergSortOrder ??= IcebergSortOrderFactory?.Build();
        result.IcebergSchemaV2 ??= IcebergSchemaV2Factory?.Build();
        result.IcebergPartitionSpec ??= IcebergPartitionSpecFactory?.Build();
    }

} // End Of Class

